package dev.kristian.nullmod.registry;

import dev.kristian.nullmod.NullMod;
import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Every sound NULL plays. The audio files are generated by tools/generate_sounds.py and
 * listed in assets/null/sounds.json under the same names.
 */
public final class NullSounds {
    public static final DeferredRegister<SoundEvent> SOUND_EVENTS = DeferredRegister.create(Registries.SOUND_EVENT, NullMod.MODID);

    // Ambience
    public static final DeferredHolder<SoundEvent, SoundEvent> STATIC_FAINT = sound("ambient.static_faint");
    public static final DeferredHolder<SoundEvent, SoundEvent> STATIC_BURST = sound("ambient.static_burst");
    public static final DeferredHolder<SoundEvent, SoundEvent> DIGITAL_INTERFERENCE = sound("ambient.digital_interference");
    public static final DeferredHolder<SoundEvent, SoundEvent> LOW_HUM = sound("ambient.low_hum");
    public static final DeferredHolder<SoundEvent, SoundEvent> RUMBLE = sound("ambient.rumble");
    public static final DeferredHolder<SoundEvent, SoundEvent> UNDERGROUND = sound("ambient.underground");
    public static final DeferredHolder<SoundEvent, SoundEvent> REVERSED = sound("ambient.reversed");
    public static final DeferredHolder<SoundEvent, SoundEvent> WHISPER = sound("ambient.whisper");
    public static final DeferredHolder<SoundEvent, SoundEvent> VOICES_DISTANT = sound("ambient.voices_distant");
    public static final DeferredHolder<SoundEvent, SoundEvent> HEARTBEAT = sound("ambient.heartbeat");
    public static final DeferredHolder<SoundEvent, SoundEvent> WRONG_WIND = sound("ambient.wrong_wind");

    // One-off events
    public static final DeferredHolder<SoundEvent, SoundEvent> FOOTSTEPS_DISTORTED = sound("event.footsteps_distorted");
    public static final DeferredHolder<SoundEvent, SoundEvent> FOOTSTEPS_PLAYER = sound("event.footsteps_player");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXPLOSION_DISTANT = sound("event.explosion_distant");
    public static final DeferredHolder<SoundEvent, SoundEvent> KNOCK = sound("event.knock");
    public static final DeferredHolder<SoundEvent, SoundEvent> GLITCH = sound("event.glitch");
    public static final DeferredHolder<SoundEvent, SoundEvent> BLACKOUT = sound("event.blackout");
    public static final DeferredHolder<SoundEvent, SoundEvent> SCREEN_TEAR = sound("event.screen_tear");
    public static final DeferredHolder<SoundEvent, SoundEvent> FREEZE = sound("event.freeze");
    public static final DeferredHolder<SoundEvent, SoundEvent> DISCONNECT = sound("event.disconnect");
    public static final DeferredHolder<SoundEvent, SoundEvent> SKY_FLICKER = sound("event.sky_flicker");
    public static final DeferredHolder<SoundEvent, SoundEvent> BREATH_BEHIND = sound("event.breath_behind");

    // The moon
    public static final DeferredHolder<SoundEvent, SoundEvent> MOON_CRACK = sound("moon.crack");
    public static final DeferredHolder<SoundEvent, SoundEvent> MOON_FRAGMENT = sound("moon.fragment");
    public static final DeferredHolder<SoundEvent, SoundEvent> MOON_SHATTER = sound("moon.shatter");
    public static final DeferredHolder<SoundEvent, SoundEvent> MOON_GONE = sound("moon.gone");

    // NULLROOT
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_IDLE = sound("nullroot.idle");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_REACH = sound("nullroot.reach");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_GRAB = sound("nullroot.grab");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_PULSE = sound("nullroot.pulse");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_CAPTURE = sound("nullroot.capture");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_CONSUME = sound("nullroot.consume");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_HURT = sound("nullroot.hurt");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_DEATH = sound("nullroot.death");
    public static final DeferredHolder<SoundEvent, SoundEvent> NULLROOT_GROW = sound("nullroot.grow");

    // Visitors and simulated players
    public static final DeferredHolder<SoundEvent, SoundEvent> VISITOR_VANISH = sound("visitor.vanish");
    public static final DeferredHolder<SoundEvent, SoundEvent> VISITOR_APPEAR = sound("visitor.appear");
    public static final DeferredHolder<SoundEvent, SoundEvent> VISITOR_BREATH = sound("visitor.breath");
    public static final DeferredHolder<SoundEvent, SoundEvent> FAKE_PLAYER_WHISPER = sound("fakeplayer.whisper");

    // The NULL dimension and the transition into it
    public static final DeferredHolder<SoundEvent, SoundEvent> TRANSITION_COLLAPSE = sound("transition.collapse");
    public static final DeferredHolder<SoundEvent, SoundEvent> TRANSITION_ARRIVAL = sound("transition.arrival");
    public static final DeferredHolder<SoundEvent, SoundEvent> DIMENSION_HUM = sound("dimension.hum");
    public static final DeferredHolder<SoundEvent, SoundEvent> DIMENSION_SHIFT = sound("dimension.shift");
    public static final DeferredHolder<SoundEvent, SoundEvent> DIMENSION_BLACKOUT = sound("dimension.blackout");

    // Music
    public static final DeferredHolder<SoundEvent, SoundEvent> MUSIC_DISTORTED_1 = sound("music.distorted_1");
    public static final DeferredHolder<SoundEvent, SoundEvent> MUSIC_DISTORTED_2 = sound("music.distorted_2");
    public static final DeferredHolder<SoundEvent, SoundEvent> MUSIC_NULL = sound("music.null_theme");

    // Corrupted blocks
    public static final DeferredHolder<SoundEvent, SoundEvent> CORRUPTED_BREAK = sound("block.corrupted.break");
    public static final DeferredHolder<SoundEvent, SoundEvent> CORRUPTED_STEP = sound("block.corrupted.step");
    public static final DeferredHolder<SoundEvent, SoundEvent> CORRUPTED_PLACE = sound("block.corrupted.place");
    public static final DeferredHolder<SoundEvent, SoundEvent> CORRUPTED_HIT = sound("block.corrupted.hit");

    // Main menu
    public static final DeferredHolder<SoundEvent, SoundEvent> MENU_AMBIENCE = sound("menu.ambience");
    public static final DeferredHolder<SoundEvent, SoundEvent> MENU_HOVER = sound("menu.hover");
    public static final DeferredHolder<SoundEvent, SoundEvent> MENU_CLICK = sound("menu.click");
    public static final DeferredHolder<SoundEvent, SoundEvent> MENU_WHISPER = sound("menu.whisper");
    public static final DeferredHolder<SoundEvent, SoundEvent> MENU_WAITING = sound("menu.waiting");

    private NullSounds() {
    }

    private static DeferredHolder<SoundEvent, SoundEvent> sound(String name) {
        return SOUND_EVENTS.register(name, () -> SoundEvent.createVariableRangeEvent(NullMod.id(name)));
    }
}
